uint8_t rx[1];
uint8_t message[] = "HAL UART ready\r\n";
HAL_UART_Transmit((&huart2), message, (sizeof(message) - 1), 100);
if ((HAL_UART_Receive((&huart2), rx, 1, 10) == HAL_OK)) {
    HAL_UART_Transmit((&huart2), rx, 1, 100);
}

uint32_t servoStep = 0;
TIM_OC_InitTypeDef channel = {0};
(channel.OCMode = TIM_OCMODE_PWM1);
(channel.OCPolarity = TIM_OCPOLARITY_HIGH);
(channel.Pulse = 1000);
HAL_TIM_PWM_ConfigChannel((&htim2), (&channel), TIM_CHANNEL_1);
HAL_TIM_PWM_Start((&htim2), TIM_CHANNEL_1);
uint32_t pulse = (1000 + (servoStep * 500));
__HAL_TIM_SET_COMPARE((&htim2), TIM_CHANNEL_1, pulse);
printf("Servo command=%lu deg pulse=%lu us\n", (servoStep * 90), pulse);
(servoStep = ((servoStep + 1) % 3));
HAL_Delay(1200);

HAL_ADC_Start((&hadc1));
